DOCUMENT();

#############
# Load Macros
#############

loadMacros(
  "PGstandard.pl",
  "PGML.pl",
  "AnswerFormatHelp.pl",
  "PGchoicemacros.pl",
  "contextForm.pl",
  "ORCCA.pl",
  "PGcourse.pl",
);
COMMENT('Authored in PreTeXt');

#######
# Setup
#######

$var = list_random('a'..'n', 'p'..'z', 'A'..'D', 'F'..'N', 'P'..'T', 'V'..'Z');
Context("Form")->variables->are($var => 'Real');
($a, $b) = (2..10)[NchooseK(9,2)];
$given = Formula("$a($var - $b)");
$ab = $a*$b;
$ans = Formula("$a $var - $a*$b");
$alt = Formula("$a $var - $ab");
$evaluator = $ans->cmp->withPostFilter(sub {
  my $ans = shift;
  $altans = $alt->cmp->evaluate($ans->{original_student_ans});
  if ($altans->{score} == 1) {
    return $altans;
  } else {
    return $ans;
  }
});

######
# Body
######

BEGIN_PGML
Apply the distributive property to [`[$given]\text{.}`]

[_]{$evaluator}{16}

END_PGML

##########
# Solution
##########

BEGIN_PGML_SOLUTION
The expression has a group of two terms multiplied by [`[$a]\text{.}`] To apply the distributive property, we multiply [`[$a]`] by each of those two terms. This gives us [`[$ans]\text{.}`]

END_PGML_SOLUTION

#############
# End Problem
#############

ENDDOCUMENT();
